function validate([head]) {
  if (!Array.isArray(head) || head.length < 1 || head.length > 30) return 'The list needs 1 to 30 nodes.';
  if (head.some(v => v !== 0 && v !== 1)) return 'Every node value must be 0 or 1.';
  return null;
}

