function getDecimalValue(head) {
  const digits = [];
  for (let p = head; p; p = p.next) digits.push(p.val);
  let result = 0;
  let power = 1;
  for (let i = digits.length - 1; i >= 0; i--) {
    result += digits[i] * power;
    power *= 2;
  }
  return result;
}

