function generate(rand, size) {
  const n = size === 'large' ? 25 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 8);
  const mode = rand();
  const onesChance = mode < 0.15 ? 0 : mode < 0.3 ? 1 : 0.5;
  const list = Array.from({ length: n }, () => (rand() < onesChance ? 1 : 0));
  return [list];
}
